/* ---------------- model ---------------- */
const VER = { M8202B:{rs:301, z:'600 Ω balanced', noise:-86, nu:' dBm', term:'TB8202/600'}, M8202:{rs:30, z:'60 Ω balanced', noise:-80, nu:' dBu', term:'TB8202'} };
const MAXIO = 24, VCA_K = -0.030, CV_TAU = 0.012, OHM_FT = 0.0257;   // +24 from the spec; SSM2018 30 mV/dB, CV filter and 24 AWG cable inferred
const D = {};
function reset(){ Object.assign(D,{ ver:'M8202B', board:'iss7', inDbu:4, f:1000, local:0.62, zero:0.35, range:0.55, offset:0.3, cmrl:0.45, cmrh:0.6, rem:false, wiper:0.5, rpot:10000, cable:300, load:600, cm:-30, sel:null, rsel:null, steps:[], w0:0.5, ev:[], inserted:true }); }
const V = ()=>VER[D.ver];
const localDb = ()=> -15+30*D.local;
const zeroErr = ()=> D.board==='iss5'? 0 : (D.zero-0.5)*6;     // ISS5 has no GAIN ZERO trim
const offErr = ()=> (D.offset-0.5)*10;
const span = ()=> 40*D.range;                             // RANGE trim: 0.75 of travel gives the manual's 30 dB
function wiperEff(w){ const rc=OHM_FT*D.cable; return (w*D.rpot+rc)/(D.rpot+2*rc); }
function wiperAt(t){ let w=D.w0; for(const s of D.steps){ if(t>=s.t){ const k=1-Math.exp(-(t-s.t)/CV_TAU); w=w+(s.w-w)*k; } } return D.steps.length? w : D.wiper; }
function vcaDb(t){ return D.rem ? (wiperEff(wiperAt(t))-0.5)*span()+offErr() : zeroErr(); }
function cmrr(){ return clamp(95-120*Math.hypot(D.cmrl-0.5,(D.cmrh-0.5)*0.5),55,95); }
function chain(t){ const on=D.inserted?0:-200; const s1=D.inDbu+localDb()+on, g=vcaDb(t==null?SIM.t:t), out=s1+g, rs=V().rs, L=D.load, atL=Math.min(out,MAXIO)+dB(L/(L+2*rs));
  const stages=[{name:'Input (TB8202 INPUT ±)', db:D.inDbu+on, g:null, note:'> 15 kΩ balanced; CMRL-R / CMRH trims'},{name:'INPUT LEVEL (front edge)', db:s1, g:localDb(), max:MAXIO, note:'local sensitivity ±15 dB'},{name:'SSM2018T VCA', db:out, g, max:MAXIO, note:D.rem?'REM GAIN IN: remote pot, RANGE, OFFSET':'REM GAIN OUT: held by GAIN ZERO'},{name:'At a load ('+L+' Ω)', db:atL, g:dB(L/(L+2*rs)), note:'2 × '+rs+' Ω'}];
  return { s1, g, out, atL, cv:g*VCA_K, clip:s1>MAXIO||out>MAXIO, total:localDb()+g, stages, cmr:cmrr(), hum:D.cm-cmrr()+localDb()+g }; }

/* ---------------- actions ---------------- */
const NAMES = { local:'INPUT LEVEL (front edge)', zero:'GAIN ZERO trim', range:'RANGE trim', offset:'OFFSET trim', cmrl:'CMRL-R trim', cmrh:'CMRH trim' };
const A = {
  set(k,v,log){ D[k]=v; if(k==='local') D.ev.push({t:SIM.t,name:'LEVEL '+localDb().toFixed(1)}); if(log) act(NAMES[k]+' adjusted', tr=>{ const c=chain();
    if(k==='local') tr(`INPUT LEVEL sets the input-stage gain ${localDb().toFixed(1)} dB → ${fmtDb(c.s1)}${c.s1>MAXIO?' — clipping before the VCA (the manual\'s caution)':''}`);
    if(k==='zero') tr(`GAIN ZERO (silk; the Issue 6 manual calls it “ZERO GAIN”) holds the SSM2018T at ${zeroErr().toFixed(2)} dB while REM GAIN is OUT`);
    if(k==='range') tr(`RANGE: the remote pot now swings the VCA over ${span().toFixed(1)} dB (manual: set for 30 dB)`);
    if(k==='offset') tr(`OFFSET: with the remote at its centre detent the VCA sits at ${offErr().toFixed(2)} dB (manual: adjust for unity)`);
    if(k==='cmrl'||k==='cmrh') tr(`CMRR ≈ ${c.cmr.toFixed(0)} dB (spec: greater than 75 dB) · hum at the output ${fmtDb(c.hum)}`);
    tr(`Overall ${c.total>=0?'+':''}${c.total.toFixed(1)} dB · card output ${fmtDb(c.out)} · ${fmtDb(c.atL)} across ${D.load} Ω`); }); },
  rem(){ act('REM GAIN jumper → '+(D.rem?'OUT':'IN'), tr=>{ D.rem=!D.rem; tr(D.rem?'REM IN (TB8202 LOW / WIPER / HIGH) now drives the SSM2018T control port':'VCA held at the GAIN ZERO setting. Manual: “must be in the OUT position if the remote control is not used”'); tr(`VCA ${vcaDb().toFixed(1)} dB`); }); },
  turn(w){ if(!D.steps.length) D.w0=D.wiper; D.steps.push({t:SIM.t,w}); D.wiper=w; D.ev.push({t:SIM.t,name:'remote '+Math.round(w*100)+'%'}); act('Remote sensitivity pot turned', tr=>{ const c=chain(SIM.t+0.1); tr(`Wiper ${Math.round(w*100)} % of a ${D.rpot/1000} k linear pot, ${D.cable} ft away: the cable adds ${(OHM_FT*D.cable).toFixed(1)} Ω per leg ${inf}, so the wiper reads ${(wiperEff(w)*100).toFixed(2)} %`); tr(`SSM2018T control ≈ ${(c.cv*1000).toFixed(0)} mV (${VCA_K*1000} mV/dB ${inf}) → ${c.g.toFixed(1)} dB after the ${CV_TAU*1000} ms control filter ${inf}`); if(!D.rem) tr('…but REM GAIN is OUT, so the VCA ignores it'); }); },
  setup(){ act('Run the M8202B set-up (manual Issue 5, steps 1–3)', tr=>{ D.rem=false; D.zero=0.5; D.local=0.5; tr('1. REM jumper OUT; adjust the local level control for unity'); D.rem=true; D.range=0.75; tr('2. 10 k linear pot on REM IN, jumper IN; RANGE for a 30 dB span'); D.wiper=0.5; D.steps=[]; D.offset=0.5; tr('3. Remote at centre detent; OFFSET for unity → ±15 dB about the centre'); }); },
  ver(v){ act('Version '+v, tr=>{ D.ver=v; tr(`${v}: outputs ${VER[v].z} on ${VER[v].term}; noise better than ${VER[v].noise}${VER[v].nu}`); }); },
  part(r){ act('Part '+r, tr=>{ D.sel=r; const p=BRD[D.board].parts.find(q=>q.ref===r); tr(`${r}: ${p&&p.v?p.v:'(value not in the PCB file)'} · ${p?p.pat:''}`); if(ROLE[r]) tr(ROLE[r]); }); },
  rrow(i){ act('TB8202 terminal '+REAR.rows[i][0], tr=>{ D.rsel=i; const s=rearSig(REAR.rows[i][0]); tr(s||'Label on M8202TR2.pdf'); }); },
  insert(){ act(D.inserted?'Pull the card out':'Slide the card in', tr=>{ D.inserted=!D.inserted; tr(D.inserted?'MF82/10 or /12: pins 1 and A at the top, handle letters read top-down. ±20 V DC, 85 mA (spec)':'Outputs silent'); }); },
  reset(){ act('Start over', tr=>{ reset(); tr('Trims as found: not yet set up'); }); },
};
const ROLE = { 'INPUT LEVEL':'POT1 on the front edge: local sensitivity', 'GAIN ZERO':'VTRIM: unity with the remote out of circuit', OFFSET:'VTRIM: VCA gain at the remote centre detent', RANGE:'VTRIM: span of the remote control', 'REM GAIN':'H1X3 jumper: remote IN / OUT', 'CMRL-R':'HTRIM: low-frequency common-mode balance', CMRH:'VCAP: high-frequency common-mode balance', U4:'U4 (DIP16): the SSM2018T VCA (DSN strings) — the largest IC on the board', R21:'301 Ω ½ W 1 %: 600 Ω output build-out (2 × 301)', R22:'301 Ω ½ W 1 % build-out', REG1:'TO-92 regulator', REG2:'TO-92 regulator', P1BA:'P1: 30-way edge connector' };
function rearSig(lab){ const c=chain(); if(/^INPUT [+-]/.test(lab)) return `${lab}: ${fmtDb(D.inDbu)}`; const m=lab.match(/OUT (\d) ([+-])/); if(m) return `OUT ${m[1]} ${m[2]}: ${fmtDb(c.atL)} balanced across ${D.load} Ω (600 Ω split)`; if(/^(LOW|WIPER|HIGH)$/.test(lab)) return `REM IN ${lab}: remote pot ${lab==='WIPER'?'wiper at '+Math.round(D.wiper*100)+' %':lab==='HIGH'?'CW end':'CCW end'}`; return null; }

/* ---------------- drawings ---------------- */
function ctl(){ const k=(key,x,y,kind,short,ly)=>({k:key,label:NAMES[key],short,kind,x,y,ly,get:()=>D[key],set:(v,l)=>A.set(key,v,l)});
  return [k('local',0.4,2.43,'multi','INPUT LEVEL',2.0), k('zero',2.625,2.505,'trim','GAIN ZERO',2.15), k('cmrl',2.875,1.58,'trim','CMRL-R',1.2), k('cmrh',2.85,2.03,'trim','CMRH',2.05), k('offset',5.425,1.105,'trim','OFFSET',1.5), k('range',5.425,0.63,'trim','RANGE',0.3),
    {k:'rem',label:'REM GAIN jumper (H1X3)',kind:'jumper',x:4.25,y:0.28,get:()=>0,show:()=>'REM '+(D.rem?'IN':'OUT'),click:()=>A.rem()}].filter(c=>!(c.k==='zero'&&D.board==='iss5')); }
function remoteSVG(){ const a=-150+300*D.wiper; return `<svg viewBox="0 0 280 150" style="width:100%;max-width:280px" role="img" aria-label="Remote pot"><rect x="5" y="5" width="270" height="140" rx="8" fill="#1d1f21"/><text x="16" y="24" font-size="11" fill="#ddd">Remote: 10 k linear, centre detent (REM IN)</text>
  <g class="rpot" style="cursor:pointer"><title>Click left/right half to turn (±10 %), scroll to fine-tune</title><circle cx="140" cy="84" r="40" fill="#2e3134" stroke="#555"/><circle cx="140" cy="84" r="29" fill="#4a4d50"/><line x1="140" y1="84" x2="${(140+27*Math.sin(a*Math.PI/180)).toFixed(1)}" y2="${(84-27*Math.cos(a*Math.PI/180)).toFixed(1)}" stroke="#fff" stroke-width="4"/></g>
  <circle cx="140" cy="38" r="2.5" fill="#fff"/><text x="62" y="138" font-size="10" fill="#aaa">CCW (LOW)</text><text x="168" y="138" font-size="10" fill="#aaa">CW (HIGH)</text><text x="130" y="138" font-size="10" fill="#aaa">0</text></svg>`; }
function panelHTML(){ const B=BRD[D.board]; B.ctl=ctl(); const c=chain();
  return card(`The card — ${D.ver} on PCB 14-212 (${D.board==='iss7'?'ISS7':'ISS5 folder'})`, boardSVG(B,{sel:D.sel})+controlsHTML())
   + `<div class="grid2"><div>${card('Front edge', handleSVG(D.ver, `<g class="hnd" style="cursor:pointer"><title>Click: slide the card ${D.inserted?'out':'in'}</title><rect x="10" y="80" width="60" height="100" fill="transparent"/></g><text x="80" y="140" font-size="11" fill="${D.inserted?'var(--accent)':'var(--warn)'}">${D.inserted?'in the frame':'pulled out'}</text>`))}${card('Remote sensitivity pot', remoteSVG()+`<div class="small">VCA ${c.g>=0?'+':''}${c.g.toFixed(1)} dB ${D.rem?'':'<span class="muted">(REM GAIN OUT: ignored)</span>'}</div>`)}</div>${card('Rear module '+V().term, rearSVG(Object.assign(REAR,{sig:rearSig}),{sel:D.rsel})+'<div class="small muted">Artwork: M8202TR2.pdf (the B uses the TB8202/600 build). Click a terminal label.</div>')}</div>`; }
function controlsHTML(){ return `<div class="small" style="display:flex;flex-wrap:wrap;gap:8px 14px;margin-top:8px;align-items:center">
  <label>Version <select data-c="ver">${Object.keys(VER).map(k=>`<option ${k===D.ver?'selected':''}>${k}</option>`).join('')}</select></label>
  <label>Input <input type="range" data-c="in" min="-20" max="24" value="${D.inDbu}"> <span class="mono">${fmtDb(D.inDbu)}</span></label>
  <label>Remote pot <select data-c="rpot">${[5000,10000,20000].map(v=>`<option value="${v}" ${v===D.rpot?'selected':''}>${v/1000} k</option>`).join('')}</select></label>
  <label>Cable <select data-c="cable">${[10,300,1000].map(v=>`<option value="${v}" ${v===D.cable?'selected':''}>${v} ft</option>`).join('')}</select></label>
  <label>Load <select data-c="load">${[600,10000].map(v=>`<option value="${v}" ${v===D.load?'selected':''}>${v>=1000?v/1000+' k':v} Ω</option>`).join('')}</select></label>
  <label>Board file <select data-c="board"><option value="iss7" ${D.board==='iss7'?'selected':''}>14-212 ISS7</option><option value="iss5" ${D.board==='iss5'?'selected':''}>ISS5 folder</option></select></label>
  <button data-c="setup">Run the manual set-up</button><button data-c="reset">Start over</button></div>`; }
function bind(root){ const B=BRD[D.board]; bindBoard(root,B,r=>A.part(r)); root.querySelectorAll('.rrow').forEach(g=>g.onclick=()=>A.rrow(+g.dataset.i)); root.querySelectorAll('.hnd').forEach(g=>g.onclick=()=>A.insert());
  root.querySelectorAll('.rpot').forEach(g=>{ g.onclick=e=>{ const r=g.getBoundingClientRect(); const up=(e.clientX-r.left)>r.width/2; A.turn(clamp(Math.round((D.wiper+(up?0.1:-0.1))*100)/100,0,1)); }; g.addEventListener('wheel',e=>{ e.preventDefault(); A.turn(clamp(Math.round((D.wiper+(e.deltaY<0?0.02:-0.02))*100)/100,0,1)); },{passive:false}); });
  root.querySelectorAll('[data-c]').forEach(e=>{ const c=e.dataset.c; if(c==='reset') e.onclick=()=>A.reset(); else if(c==='setup') e.onclick=()=>A.setup(); else if(c==='in') e.oninput=()=>{ D.inDbu=+e.value; SIM.refresh(); };
    else e.onchange=()=>{ const v=e.value; if(c==='ver') A.ver(v); else if(c==='board'){ D.board=v; SIM.refresh(); } else { D[c]=+v; SIM.refresh(); } }; }); }
function stateHTML(){ const c=chain(); return `<table class="kv"><tr><th>REM GAIN</th><td>${D.rem?'IN (remote active)':'OUT'}</td></tr><tr><th>Local / VCA</th><td class="mono">${localDb().toFixed(1)} / ${c.g.toFixed(1)} dB</td></tr><tr><th>Remote span</th><td class="mono">${span().toFixed(1)} dB (RANGE) · offset ${offErr().toFixed(1)} dB</td></tr><tr><th>SSM2018 control</th><td class="mono">${(c.cv*1000).toFixed(0)} mV ${inf}</td></tr><tr><th>Output</th><td class="mono">${fmtDb(c.out)} card · ${fmtDb(c.atL)} at ${D.load} Ω${c.clip?' · CLIP':''}</td></tr><tr><th>CMRR</th><td class="mono">${c.cmr.toFixed(0)} dB</td></tr><tr><th>Noise</th><td class="mono">better than ${V().noise}${V().nu} (spec)</td></tr></table>`; }
function lanes(){ const c=chain(), f=D.f;
  return [ waveLane('Input (TB8202 INPUT ±)', 40, t=>sineV(t,D.inserted?D.inDbu:-200,f), {f, col:SIM.css('--ink2')}),
    waveLane('After INPUT LEVEL', 40, t=>sineV(t,c.s1,f,MAXIO), {f, clip:MAXIO}),
    valueLane('Remote wiper (REM IN)', 30, t=>wiperAt(t)*100, 0, 100, {fmt:v=>v.toFixed(1)+' %'}),
    valueLane('SSM2018T control voltage', 30, t=>vcaDb(t)*VCA_K*1000, -600, 600, {fmt:v=>v.toFixed(0)+' mV', col:SIM.css('--warn')}),
    waveLane('Card output (VCA out)', 46, t=>sineV(t,D.inDbu+localDb()+vcaDb(t),f,MAXIO), {f, clip:MAXIO, col:SIM.css('--accent2')}),
    waveLane('OUT 1 across '+D.load+' Ω', 40, t=>sineV(t,Math.min(D.inDbu+localDb()+vcaDb(t),MAXIO)+dB(D.load/(D.load+2*V().rs)),f), {f}),
    eventLane('Your adjustments', ()=>D.ev) ]; }
function secondHTML(){ const c=chain(); return `<table class="kv"><tr><th>Tone</th><td class="mono">${D.f} cycles</td></tr><tr><th>Remote moves</th><td class="mono">${D.steps.length} this second; each settles in ≈ ${(CV_TAU*5*1000).toFixed(0)} ms ${inf}</td></tr><tr><th>Cable</th><td class="mono">${D.cable} ft · ${(OHM_FT*D.cable).toFixed(1)} Ω per leg ${inf} (spec: up to 1000 ft / 300 m)</td></tr><tr><th>Into 600 Ω</th><td class="mono">${(dBu2V(Math.min(c.out,MAXIO))/(D.load+2*V().rs)*1000).toFixed(2)} mA rms per output</td></tr><tr><th>Supply</th><td class="mono">±20 V DC, 85 mA (spec)</td></tr></table><p class="small">Turn the remote pot (Simulator tab) while the transport plays: the timeline shows the wiper step, the control voltage easing to its new value, and the output following.</p>`; }

const lessons=[
  {title:'The card', auto:true, check:()=>true, body:'<p>The M8202B is the 600 Ω version of the remote-sensitivity DA. Its gain can be varied ±15 dB by the local level control or by a 10 k centre-detent pot up to 1000 ft away, wired to REM IN on the TB8202 (M8202BMN, Issue 5).</p>'},
  {title:'1 · Unity with the remote out', check:()=>!D.rem&&Math.abs(localDb()+zeroErr())<0.4, hint:'REM jumper OUT. Then step INPUT LEVEL (front edge) until the overall gain is 0.', body:'<p>Set-up step 1 (Issue 5): jumper in the “OUT” position, feed nominal level, adjust the <b>local level control</b> for unity.</p><p><b>Goal:</b> REM OUT and overall gain within 0.4 dB of unity.</p>'},
  {title:'2 · Set the remote range', check:()=>D.rem&&Math.abs(span()-30)<1.5, hint:'Click REM to IN, then step RANGE until the span reads 30 dB.', body:'<p>Step 2: connect the 10 k linear pot to REM IN, move the jumper to IN, and set <b>RANGE</b> for a 30 dB span.</p><p><b>Goal:</b> jumper IN and a 30 dB span (±1.5).</p>'},
  {title:'3 · Centre the remote', check:()=>D.rem&&Math.abs(D.wiper-0.5)<0.01&&Math.abs(offErr())<0.4, hint:'Remote pot at the centre dot, then OFFSET until the VCA reads 0 dB.', body:'<p>Step 3: put the remote at its centre detent and set <b>OFFSET</b> for unity. The remote now spans ±15 dB about the centre.</p><p><b>Goal:</b> remote centred and VCA within 0.4 dB of 0.</p>'},
  {title:'4 · The caution', check:()=>chain().s1>MAXIO, hint:'Raise the input to +20 and INPUT LEVEL near full.', body:'<p>The manual warns: do not use the local gain to set the operating range — it can clip before the VCA. Show it.</p><p><b>Goal:</b> clip the input stage.</p>'},
  {title:'5 · A long remote run', check:()=>D.cable===1000&&D.steps.length>0, hint:'Cable → 1000 ft, then turn the remote pot.', body:'<p>The remote wiper drives a high-impedance control input, so 1000 ft of cable shifts the reading by only a fraction of a percent.</p><p><b>Goal:</b> 1000 ft of cable and a remote move.</p>'},
  {title:'Done', auto:true, check:()=>true, body:'<p>See <b>Findings</b>, and the M8202RC plugin for the 12-pot remote panel.</p>'},
];
const blocks={ w:820, h:270, note:'From the M8202B DSN strings and the 14-212 parts; the LDR stage on the AutoCAD sheets is the earlier design.', nodes:{
  tb:{x:10,y:40,w:110,h:52,t:'TB8202/600',s:['INPUT ±, SH'],lv:()=>fmtDb(D.inDbu),info:'Screw terminals: INPUT, OUT 1–8 (600 Ω splits on the B), REM IN LOW / WIPER / HIGH.'},
  ia:{x:150,y:40,w:150,h:52,t:'Input amp',s:['CMRL-R, CMRH','INPUT LEVEL ±15 dB'],lv:()=>fmtDb(chain().s1),info:()=>`Balanced input stage; CMRR ≈ ${cmrr().toFixed(0)} dB.`},
  vca:{x:330,y:40,w:150,h:52,t:'SSM2018T VCA',s:['U4 (DIP16)'],lv:()=>chain().g.toFixed(1)+' dB',info:'The gain element on 14-212 ISS 5/6 (DSN). The 1995 AutoCAD sheets use a VTL5C4 opto (LDR1) instead.'},
  ob:{x:510,y:40,w:140,h:52,t:'Output stage',s:['Q1–Q4, 301 Ω ½ W'],lv:()=>fmtDb(chain().out),info:'Discrete output transistors; 301 Ω ½ W 1 % build-outs give the 600 Ω outputs.'},
  out:{x:680,y:40,w:130,h:52,t:'OUT 1–8',s:['600 Ω splits'],lv:()=>fmtDb(chain().atL),info:'Eight balanced splits on the TB8202/600.'},
  rem:{x:150,y:170,w:150,h:52,t:'REM IN',s:['10 k pot, ≤ 1000 ft'],lv:()=>Math.round(D.wiper*100)+' %',info:'Remote pot (M8202RC panel or any 5–20 kΩ linear pot).'},
  jp:{x:330,y:170,w:150,h:52,t:'REM GAIN jumper',s:['RANGE, OFFSET','GAIN ZERO'],lv:()=>D.rem?'IN':'OUT',info:'Selects the remote control voltage (IN) or the GAIN ZERO preset (OUT).'} },
  edges:[['tb','ia'],['ia','vca'],['vca','ob'],['ob','out'],['rem','jp'],['jp','vca','control']] };
function partsSheet(hl){ const B=BRD[D.board], H=(hl&&hl[0]||'').toUpperCase(); const ps=B.parts.filter(p=>!H||p.ref.toUpperCase().includes(H)||String(p.v).toUpperCase().includes(H)).sort((a,b)=>a.ref.localeCompare(b.ref,undefined,{numeric:true}));
  return `<table class="kv small"><tr><th>Ref</th><th>Value (PCB file)</th><th>Footprint</th><th>x, y (in)</th><th>Role</th></tr>${ps.map(p=>`<tr><td class="mono">${esc(p.ref)}</td><td class="mono">${esc(p.v||'—')}</td><td class="mono">${esc(p.pat)}</td><td class="mono">${p.x.toFixed(2)}, ${p.y.toFixed(2)}</td><td class="small">${ROLE[p.ref]||''}</td></tr>`).join('')}</table>`; }
const sheets=[
  {name:'XSM8202A.DWG — ISS 2 schematic', J:XSM, note:'B 8202-02-002, “M8202A REMOTE SENITIVITY AMPLIFIER” (sic), redrawn from the R12 file. This is the earlier opto design: LDR1 VTL5C4 in a heat-sunk pair (Q5/Q6 2N3904).'},
  {name:'SM8202A.DWG — earlier sheet', J:SM, note:'The same circuit on a larger sheet (input −20 to +10 dBu, outputs 0 to +8 dBu, 30.1 Ω 1 W).'},
  {name:'14-212 ISS7 parts (from the PCB file)', svg:partsSheet, note:'Every COMP record of the Tango file; values are present only where the designer typed them (the 301 Ω build-outs).'} ];
function softHTML(){ const c=chain(); return `<div class="grid2">${card('Signal path, stage by stage', stageTable(c.stages))}${card('Level diagram', levelSVG(c.stages))}</div>
  <div class="grid2">${card('Remote control maths', `<table class="kv"><tr><th>Wiper</th><td class="mono">${(D.wiper*100).toFixed(0)} % → effective ${(wiperEff(D.wiper)*100).toFixed(2)} %</td></tr><tr><th>VCA gain</th><td class="mono">(wiper − 0.5) × ${span().toFixed(1)} dB + ${offErr().toFixed(2)} dB = ${vcaDb().toFixed(2)} dB</td></tr><tr><th>Control port</th><td class="mono">${(vcaDb()*VCA_K*1000).toFixed(0)} mV at ${VCA_K*1000} mV/dB ${inf}</td></tr><tr><th>REM OUT</th><td class="mono">GAIN ZERO: ${zeroErr().toFixed(2)} dB</td></tr></table>`)}
  ${card('Version table', `<table class="kv"><tr><th></th><th>M8202 (Issue 6)</th><th>M8202B (Issue 5)</th></tr><tr><td>Outputs</td><td>60 Ω</td><td>600 Ω</td></tr><tr><td>Noise</td><td>−80 dBu</td><td>−86 dBm</td></tr><tr><td>Max I/O</td><td>+24 dBu</td><td>+24 dBm</td></tr><tr><td>Set-up step 1</td><td>local at centre, adjust ZERO GAIN</td><td>adjust the local level control</td></tr><tr><td>Termination</td><td>TB8202</td><td>TB8202/600</td></tr></table>`)}</div>`; }
const findings=[
  `<b>The schematics show a different gain element.</b> XSM8202A.DWG / SM8202A.DWG (1995–1998) control the gain with an opto-resistor, “LDR1 VTL 5C4”, next to a heat-sunk transistor pair (Q5/Q6 2N3904, “HEATSINK 7840-016-1”). The OrCAD files for PCB 14-212 ISS 5 and ISS 6 (<span class="mono">M8202B.DSN</span>, JUNE 14,1998 and AUG 13,1998) use an <b>SSM2018T</b> VCA. The only drawable schematic is the older design.`,
  `<b>The two manuals give different set-ups.</b> Issue 5 (M8202B) step 1: “adjust the local level control for unity”. Issue 6 (M8202): “turn the local level control to the center detent … adjust the ZERO GAIN control”. The silk on 14-212 calls that trim <b>GAIN ZERO</b>.`,
  `<b>Units drift between the manuals.</b> M8202B: noise “−86 dBm”, max I/O “+24 dBm”; M8202: “−80 dBu”, “+24 dBu”. The M8202 page is also marked PRELIMINARY.`,
  `<b>The board file is the B build.</b> 14-212.PCB carries values only on nine resistors, all “301 1/2W 1%” (R21, R22, R26, R27, R43–R47): the 600 Ω build-outs. The DSN's value field reads “30\\300R”.`,
  `<b>Spelling.</b> The XSM8202A title block reads “REMOTE SENITIVITY AMPLIFIER”.`,
  `<b>Duplicate folders.</b> The M8202B folder holds copies of the M8202A manuals and <span class="mono">M8202B.DBK</span> (an OrCAD backup with no extractable text). `,
  `<b>The manuals track the board issues.</b> The ISS5 copy of 14-212.PCB (silk “14-212.TOP,ISS5”) has no GAIN ZERO trim and no fuses; ISS7 adds exactly three parts: <b>GAIN ZERO</b>, F1 and F2. That explains the Issue 5 manual's “adjust the local level control for unity” and the Issue 6 manual's “ZERO GAIN” step. Switch the board file to see the trim disappear.`,
  `<b>Odd remote wiring.</b> The M8202RC drawing (RC1) routes the cable shield to EDAC pin C and on to REM IN HIGH; see the M8202RC plugin.`,
];
const assume=[`SSM2018T control constant (−30 mV/dB) and the 12 ms control filter ${inf}.`,`RANGE scaling (0.75 of travel = 30 dB) and the OFFSET / GAIN ZERO error ranges ${inf}.`,`Cable resistance 0.0257 Ω/ft (24 AWG) ${inf}.`,`Control positions are the COMP coordinates of 14-212.PCB.`];
P={ id:'m8202b', product:'M8202B', year:1998, family:'8200 Distribution Series', folder:'#MF8200 #SERIES/M8202B - #Master #MF82',
  name:'M8202B · Remote-sensitivity DA, 600 Ω (1998|31)',
  summary:'The 600 Ω version of Ward-Beck\'s remote-sensitivity analog distribution amplifier: ±15 dB of gain set locally or by a 10 k pot up to 1000 ft away. Run the manual\'s set-up with the real trims on the 14-212 board, turn the remote pot and watch the VCA follow.',
  highlights:['PCB 14-212 rendered from its Tango file, trims live','Manual set-up: GAIN ZERO, RANGE, OFFSET, REM jumper','Remote pot with cable length','Schematics redrawn from the R12 DWGs (opto design)','Issue 5 vs Issue 6 manual differences'],
  hint:'Click a trim on the board (INPUT LEVEL, GAIN ZERO, RANGE, OFFSET, CMRL-R, CMRH), the REM jumper, the remote knob, or a TB8202 terminal.',
  reset, chain, lanes, panelHTML, bind, stateHTML, secondHTML, lessons, blocks, sheets, softHTML, findings, assume,
  tutPanel:()=>card('The card', boardSVG(Object.assign(BRD[D.board],{ctl:ctl()}),{sel:D.sel})+controlsHTML())+card('Remote', remoteSVG())+card('State', stateHTML()),
  sources:['M8202B - #Master #MF82/M8202BMN.pdf, M8202BMN.WPD, M8202MAN.pdf, M8202B.DBK','M8202A - #Engineering #MF82/M8202A - #PCB 14-212/14-212.PCB, M8202B.DSN, M8202.DSN','M8202A - #Engineering #MF82/M8202A - ISS5 #GERBER/14-212.PCB, M8202B.DSN','M8202A - #Engineering #MF82/M8202A - 14-212/XSM8202A.DWG, SM8202A.DWG, M8202TR2.pdf, M8202.DSN','M8202RC - #Engineering #MF82/M8202RC1.DWG','8205-004 ISS 2 (HANDLE) .pdf'] };
